package com.bank.document.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

@Service
@Slf4j
public class Base64EncodingService {

    /**
     * BASIC Base64: standard encoding.
     * Uses: A-Z, a-z, 0-9, +, /
     * Padding: = (at the end)
     * Use for: general binary-to-text (store in DB, send in JSON body)
     */
    public String encodeBasic(byte[] data) {
        String encoded = Base64.getEncoder().encodeToString(data);
        log.info("[BASIC] Original: {} bytes → Encoded: {} chars (33% larger)",
            data.length, encoded.length());
        return encoded;
    }

    public byte[] decodeBasic(String encoded) {
        byte[] decoded = Base64.getDecoder().decode(encoded);
        log.info("[BASIC] Decoded: {} bytes", decoded.length);
        return decoded;
    }

    /**
     * URL-SAFE Base64: safe for URLs and query parameters.
     * Replaces + with - and / with _ (these are special in URLs)
     * No padding by default (= is special in query params)
     * Use for: JWT tokens, URL parameters, file download links
     */
    public String encodeUrlSafe(byte[] data) {
        String encoded = Base64.getUrlEncoder().withoutPadding().encodeToString(data);
        log.info("[URL-SAFE] No +, no /, no = → safe in URLs: {}", encoded.substring(0, Math.min(50, encoded.length())));
        return encoded;
    }

    public byte[] decodeUrlSafe(String encoded) {
        return Base64.getUrlDecoder().decode(encoded);
    }

    /**
     * MIME Base64: line-wrapped at 76 characters.
     * Use for: email attachments (SMTP requires line length limits)
     * Rarely used in REST APIs.
     */
    public String encodeMime(byte[] data) {
        String encoded = Base64.getMimeEncoder().encodeToString(data);
        log.info("[MIME] Line-wrapped at 76 chars (for email): {} chars", encoded.length());
        return encoded;
    }

    /**
     * DEMONSTRATION: Base64 is NOT encryption!
     * Anyone can decode it. It provides ZERO security.
     */
    public String demonstrateNotEncryption() {
        String secret = "Account SAV2001 has balance Rs.10,00,000";

        // "Encode" (NOT encrypt!)
        String encoded = Base64.getEncoder().encodeToString(secret.getBytes(StandardCharsets.UTF_8));
        log.warn("[NOT ENCRYPTION] Encoded: {}", encoded);

        // Anyone can decode — zero security!
        String decoded = new String(Base64.getDecoder().decode(encoded), StandardCharsets.UTF_8);
        log.warn("[NOT ENCRYPTION] Decoded by ANYONE: {}", decoded);

        return "Base64 encoded: " + encoded + " | Decoded by anyone: " + decoded
            + " | *** THIS IS NOT ENCRYPTION — ANYONE CAN DECODE! ***";
    }

    /**
     * CORRECT for sensitive data: Encrypt FIRST (AES), THEN Base64 encode for transport.
     * Decrypt: Base64 decode → AES decrypt.
     * Base64 makes the ciphertext (binary) transportable as text.
     */
    public String correctApproach() {
        return "Step 1: AES encrypt the data (produces binary ciphertext). " +
               "Step 2: Base64 encode the ciphertext (makes it text-safe for JSON/URL). " +
               "Step 3: Receiver Base64 decodes → AES decrypts with the key. " +
               "Base64 alone = encoding (readable by all). AES = encryption (key required).";
    }
}
