// JWT uses Base64URL encoding for header and payload
package com.bank.document.service;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

@Service
@Slf4j
public class JwtDemoService {

    /**
     * JWT structure: header.payload.signature
     * Header and payload are Base64URL-encoded JSON (NOT encrypted!)
     * Anyone can decode the header and payload — they are PUBLIC.
     * Only the SIGNATURE provides integrity (tamper detection).
     * The signature is created with a SECRET KEY — that's the security part.
     */
    public String demonstrateJwtEncoding() {
        String header = "{\"alg\":\"HS256\",\"typ\":\"JWT\"}";
        String payload = "{\"sub\":\"rajesh@bank.com\",\"role\":\"USER\",\"exp\":1705334400}";

        // JWT uses Base64URL (no padding, URL-safe characters)
        String encodedHeader = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(header.getBytes(StandardCharsets.UTF_8));
        String encodedPayload = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(payload.getBytes(StandardCharsets.UTF_8));

        log.info("JWT header (Base64URL): {}", encodedHeader);
        log.info("JWT payload (Base64URL): {}", encodedPayload);

        // Anyone can decode these — they are NOT secret!
        String decodedPayload = new String(
            Base64.getUrlDecoder().decode(encodedPayload), StandardCharsets.UTF_8);
        log.warn("Decoded payload (by ANYONE): {}", decodedPayload);
        log.warn("JWT payload is PUBLIC — never store sensitive data in JWT payload!");

        return "header=" + encodedHeader + " | payload=" + encodedPayload
            + " | *** Payload is readable by ANYONE — not encrypted! ***";
    }
}
