package com.bank.document.controller;

import com.bank.document.dto.*;
import com.bank.document.service.*;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.nio.charset.StandardCharsets;

@RestController
@RequestMapping("/api/v1/documents")
@RequiredArgsConstructor
public class DocumentController {

    private final Base64EncodingService encodingService;
    private final JwtDemoService jwtService;

    @PostMapping("/encode")
    public DocumentResponse encode(@RequestBody @Valid DocumentUploadRequest request) {
        byte[] content = request.base64Content().getBytes(StandardCharsets.UTF_8);
        String basicEncoded = encodingService.encodeBasic(content);
        String urlSafeEncoded = encodingService.encodeUrlSafe(content);

        return new DocumentResponse(request.accountId(), request.documentType(),
            basicEncoded, content.length, basicEncoded.length(), "BASIC",
            "Base64 is encoding NOT encryption — anyone can decode!");
    }

    @GetMapping("/demo/not-encryption")
    public String demoNotEncryption() {
        return encodingService.demonstrateNotEncryption();
    }

    @GetMapping("/demo/jwt-encoding")
    public String demoJwt() {
        return jwtService.demonstrateJwtEncoding();
    }

    @GetMapping("/demo/correct-approach")
    public String correctApproach() {
        return encodingService.correctApproach();
    }
}
