package com.bank.document.service;

import org.junit.jupiter.api.Test;
import java.nio.charset.StandardCharsets;
import static org.assertj.core.api.Assertions.*;

class Base64EncodingServiceTest {

    Base64EncodingService service = new Base64EncodingService();

    @Test
    void shouldEncodeAndDecodeBasic() {
        byte[] original = "Rajesh Kumar - SAV2001".getBytes(StandardCharsets.UTF_8);
        String encoded = service.encodeBasic(original);
        byte[] decoded = service.decodeBasic(encoded);

        assertThat(new String(decoded, StandardCharsets.UTF_8)).isEqualTo("Rajesh Kumar - SAV2001");
        assertThat(encoded.length()).isGreaterThan(original.length); // ~33% larger
    }

    @Test
    void shouldEncodeUrlSafeWithoutSpecialChars() {
        byte[] data = {(byte)0xFF, (byte)0xFE, (byte)0xFD}; // binary data
        String encoded = service.encodeUrlSafe(data);

        assertThat(encoded).doesNotContain("+", "/", "="); // URL-safe!
    }

    @Test
    void shouldRoundTripUrlSafe() {
        byte[] original = "account=SAV2001&balance=1000000".getBytes(StandardCharsets.UTF_8);
        String encoded = service.encodeUrlSafe(original);
        byte[] decoded = service.decodeUrlSafe(encoded);

        assertThat(decoded).isEqualTo(original);
    }

    @Test
    void shouldProveBase64IsNotEncryption() {
        // ANYONE can decode Base64 — no key needed!
        String encoded = java.util.Base64.getEncoder()
            .encodeToString("SECRET DATA".getBytes(StandardCharsets.UTF_8));
        String decoded = new String(java.util.Base64.getDecoder().decode(encoded), StandardCharsets.UTF_8);
        assertThat(decoded).isEqualTo("SECRET DATA"); // zero security!
    }
}
